import{_ as r,o as t,c as e,a2 as s}from"./chunks/framework.B2QVIpOM.js";const h=JSON.parse('{"title":"拔萃女书院 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-5234a481","school_zh":"拔萃女书院","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"拔萃女书院 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-DGS-EARLY","C2223-DGS-FIRST","C2223-DGS-FOLLOWUP"],"rounds":["unknown","r1"]},"headers":[],"relativePath":"reports/school-5234a481/s1/2022-23-interview.md","filePath":"reports/school-5234a481/s1/2022-23-interview.md"}'),a={name:"reports/school-5234a481/s1/2022-23-interview.md"};function p(n,o,c,l,g,d){return t(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="拔萃女书院-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">拔萃女书院 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#拔萃女书院-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;拔萃女书院 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-5234a481">← 返回拔萃女书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-dgs-early" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-dgs-early" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-dgs-early}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>提前面见资料</strong></p><p>以下为合集明确标注Early Bird的一组反馈，与常规首轮分开。</p></blockquote><blockquote><p><strong>语文：</strong> 中文，口语未注明</p><p><strong>朗读与家庭沟通</strong></p><p>读一篇作者不喜欢吃饭的文章，约两分钟；认读词语，包括“不胜枚举”“窜改”“络绎不绝”等。问家里有没有长辈，觉得长辈啰嗦时怎样增进沟通，以及认为自己哪方面比旁边同学强。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>文章、介绍及音乐联想</strong></p><p>朗读望远镜主题文章的两段，作自我介绍，谈喜欢的食物及爱好；用一首古典乐曲形容当下的面试心情。</p></blockquote><blockquote><p><strong>学生面试：</strong> 语言未注明</p><p><strong>选校比较</strong></p><p>还想报考哪些学校；若两所学校都录取，会选择哪所及原因。</p></blockquote><h2 id="record-c2223-dgs-first" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-dgs-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-dgs-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 中文，口语未注明</p><p><strong>短文与文言文</strong></p><p>朗读短文后问作者如何面对困难，除了坚强还需要何种心态才能成功；另有菊花主题文言文及两道内容问题。</p><p><strong>怀疑与阅读风气</strong></p><p>有考生先用约20秒看文章及问题，再朗读并回答“作者要传达什么讯息”和“怎样改善学校阅读风气”；材料主题包含“小疑则小进，大疑则大进，不疑则不悟”。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗读及一分钟表达</strong></p><p>多份记录有较长文章，约一分钟准备、一分钟朗读，再用一分钟答一道问题；有学生称读不完全文。问题包括是否想乘太空船、喜欢什么动物、独生子女与有兄弟姐妹的生活、是否想成为企鹅、是否想在海洋公园工作及原因。</p><p><strong>延伸问答差异</strong></p><p>有考生被问圣诞节到哪里，感觉与刚读的文章无关；另有人的问题与文章相连，因此并非每次只考文章内容。</p></blockquote><blockquote><p><strong>数学：</strong> 英语</p><p><strong>平板看题、口头回答</strong></p><p>有考生需在4分半钟内完成20题，可以跳题；题型有规律、最小公倍数、小数和分数加减，以及考生形容为奥数的推理题。</p></blockquote><blockquote><p><strong>考核体验：</strong></p><p><strong>等候与时长</strong></p><p>有记录先与约50名学生在礼堂看面试说明，家长约一小时后接回孩子。</p></blockquote><h2 id="record-c2223-dgs-followup" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-dgs-followup" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-dgs-followup}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>家长短暂陪同</strong></p><p>家长与孩子一同进入，孩子先介绍陪同者，随后家长在外等候。</p></blockquote><blockquote><p><strong>学生面试：</strong> 语言未注明</p><p><strong>家庭、学业与贡献</strong></p><p>父亲从事什么工作、未来怎样贡献社会、平时怎样学数学及为何数学表现突出。考官依据考生的年级成绩和比赛经历追问，并就资料中的academic scholarship询问它与academic award的区别。</p></blockquote>',28)])])}const u=r(a,[["render",p]]);export{h as __pageData,u as default};
